-- DU LIEU DEMO V2: 70 san pham, 830 bien the, 208 anh Cloudinary, 300 don, 100 danh gia, 10 phieu TRA HANG.
-- HeidiSQL: mo file trong tab Query, chon database fashion-website, autocommit ON.
-- Chon Send queries one by one (khong chon Send batch in one go), Ctrl+A va chay toan bo file.
-- DELIMITER ^^ giu nguyen ca khoi BEGIN ... END khi gui den MariaDB.
-- Chay Spring Boot truoc de tao bang va tai khoan. Khong tao/sua tai khoan, dia chi, gio hang.
-- Dung khach hang ACTIVE co san; thong tin giao hang lay tu khach hang luc nhap.
-- Giu lich su gia lap 01/01-22/10/2026. Ngay tao tai khoan la ngay khoi tao/nhap thu nghiem, khong phai ngay khach that dang ky.
-- Khong co doi hang. Hoan tien sau nhan/kiem hang; khong hoan phi giao ban dau.
-- Phi gui tra 25.000d chi la bao gia gia lap cho ly do doi y; co xac nhan dong y.
-- Tat ca thanh toan/chung tu trong file la gia lap, KHONG chuyen tien that.
-- Phieu PENDING/APPROVED qua han duoc ghi ro trong JSON ly do; chua hoan tien.
-- Entity chi co 4 trang thai tra hang; cac moc nhan/kiem/hoan duoc luu mo phong trong reason_detail/gateway_response.
-- Chay lai: nhap batch con thieu, sua dung batch FW-DEMO-V1 cu sang V2; batch V2 hop le duoc giu nguyen.
-- Neu database da co V1, hay sao luu truoc: file nay se CAP NHAT cac ban ghi demo cu, khong chi INSERT.
-- delivered_at la moc giao thanh cong; chay Spring Boot ban moi truoc khi import.
DELIMITER ^^
BEGIN NOT ATOMIC
  DECLARE v_lock_coolmate INT DEFAULT 0;
  DECLARE v_lock_owen INT DEFAULT 0;
  DECLARE v_tx_started BOOLEAN DEFAULT FALSE;
  DECLARE v_customers INT DEFAULT 0;
  DECLARE v_offset INT DEFAULT 0;
  DECLARE v_coolmate_exists BOOLEAN DEFAULT FALSE;
  DECLARE v_owen_exists BOOLEAN DEFAULT FALSE;
  DECLARE v_legacy BOOLEAN DEFAULT FALSE;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    IF v_tx_started THEN ROLLBACK; END IF;
    IF v_lock_owen=1 THEN DO RELEASE_LOCK(CONCAT('fashion-owen-v1:',MD5(DATABASE()))); END IF;
    IF v_lock_coolmate=1 THEN DO RELEASE_LOCK(CONCAT('fashion-demo-v1:',DATABASE())); END IF;
    RESIGNAL;
  END;
  IF DATABASE() IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chon database truoc'; END IF;
  IF @@autocommit<>1 OR @@in_transaction<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Dung ket noi moi, autocommit ON, khong co giao dich dang mo'; END IF;
  SELECT GET_LOCK(CONCAT('fashion-demo-v1:',DATABASE()),15) INTO v_lock_coolmate;
  SELECT GET_LOCK(CONCAT('fashion-owen-v1:',MD5(DATABASE())),15) INTO v_lock_owen;
  IF COALESCE(v_lock_coolmate,0)<>1 OR COALESCE(v_lock_owen,0)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Dang co tien trinh khac nhap demo'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='users' AND engine='InnoDB')<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chay Spring Boot de JPA tao bang users truoc'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='categories' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: categories'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='categories' AND column_name IN ('name', 'slug', 'is_active', 'parent_id', 'created_at', 'updated_at')) <> 6 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: categories'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='categories' AND column_name NOT IN ('name', 'slug', 'is_active', 'parent_id', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: categories'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='products' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: products'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='products' AND column_name IN ('name', 'slug', 'description', 'base_price', 'average_rating', 'review_count', 'is_active', 'deleted_at', 'category_id', 'created_at', 'updated_at')) <> 11 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: products'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='products' AND column_name NOT IN ('name', 'slug', 'description', 'base_price', 'average_rating', 'review_count', 'is_active', 'deleted_at', 'category_id', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: products'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='product_variants' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: product_variants'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='product_variants' AND column_name IN ('product_id', 'sku', 'color', 'size', 'price', 'stock_quantity', 'is_active', 'created_at', 'updated_at')) <> 9 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: product_variants'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='product_variants' AND column_name NOT IN ('product_id', 'sku', 'color', 'size', 'price', 'stock_quantity', 'is_active', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: product_variants'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='product_images' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: product_images'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='product_images' AND column_name IN ('product_id', 'variant_id', 'image_url', 'is_main', 'display_order', 'created_at', 'updated_at')) <> 7 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: product_images'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='product_images' AND column_name NOT IN ('product_id', 'variant_id', 'image_url', 'is_main', 'display_order', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: product_images'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='payment_methods' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: payment_methods'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='payment_methods' AND column_name IN ('code', 'name', 'description', 'icon_url', 'is_active', 'created_at', 'updated_at')) <> 7 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: payment_methods'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='payment_methods' AND column_name NOT IN ('code', 'name', 'description', 'icon_url', 'is_active', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: payment_methods'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='special_offers' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: special_offers'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='special_offers' AND column_name IN ('title', 'discount_percent', 'discount_amount', 'offer_type', 'min_order_amount', 'max_discount_amount', 'start_date', 'end_date', 'is_active', 'created_at', 'updated_at')) <> 11 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: special_offers'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='special_offers' AND column_name NOT IN ('title', 'discount_percent', 'discount_amount', 'offer_type', 'min_order_amount', 'max_discount_amount', 'start_date', 'end_date', 'is_active', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: special_offers'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='special_offer_products' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: special_offer_products'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='special_offer_products' AND column_name IN ('special_offer_id', 'product_id', 'product_variant_id', 'created_at', 'updated_at')) <> 5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: special_offer_products'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='special_offer_products' AND column_name NOT IN ('special_offer_id', 'product_id', 'product_variant_id', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: special_offer_products'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='orders' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: orders'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='orders' AND column_name IN ('order_code', 'user_id', 'shipping_recipient_name', 'shipping_phone', 'shipping_address', 'subtotal', 'shipping_fee', 'discount_amount', 'total_amount', 'order_status', 'payment_status', 'notes', 'created_at', 'updated_at')) <> 14 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: orders'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='orders' AND column_name NOT IN ('order_code', 'user_id', 'shipping_recipient_name', 'shipping_phone', 'shipping_address', 'subtotal', 'shipping_fee', 'discount_amount', 'total_amount', 'order_status', 'payment_status', 'notes', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: orders'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='order_items' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: order_items'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='order_items' AND column_name IN ('order_id', 'variant_id', 'product_name', 'variant_info', 'original_price', 'unit_price', 'quantity', 'total_price', 'created_at', 'updated_at')) <> 10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: order_items'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='order_items' AND column_name NOT IN ('order_id', 'variant_id', 'product_name', 'variant_info', 'original_price', 'unit_price', 'quantity', 'total_price', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: order_items'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='payment_transactions' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: payment_transactions'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='payment_transactions' AND column_name IN ('transaction_code', 'amount', 'status', 'gateway_response', 'paid_at', 'order_id', 'payment_method_id', 'created_at', 'updated_at')) <> 9 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: payment_transactions'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='payment_transactions' AND column_name NOT IN ('transaction_code', 'amount', 'status', 'gateway_response', 'paid_at', 'order_id', 'payment_method_id', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: payment_transactions'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='return_requests' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: return_requests'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='return_requests' AND column_name IN ('return_code', 'user_id', 'order_id', 'request_type', 'reason', 'reason_detail', 'status', 'difference_amount', 'created_at', 'updated_at')) <> 10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: return_requests'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='return_requests' AND column_name NOT IN ('return_code', 'user_id', 'order_id', 'request_type', 'reason', 'reason_detail', 'status', 'difference_amount', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: return_requests'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='return_request_items' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: return_request_items'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='return_request_items' AND column_name IN ('return_request_id', 'order_item_id', 'old_variant_id', 'new_variant_id', 'quantity', 'created_at', 'updated_at')) <> 7 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: return_request_items'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='return_request_items' AND column_name NOT IN ('return_request_id', 'order_item_id', 'old_variant_id', 'new_variant_id', 'quantity', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: return_request_items'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='return_request_images' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: return_request_images'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='return_request_images' AND column_name IN ('return_request_id', 'image_url', 'created_at', 'updated_at')) <> 4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: return_request_images'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='return_request_images' AND column_name NOT IN ('return_request_id', 'image_url', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: return_request_images'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='product_reviews' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: product_reviews'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='product_reviews' AND column_name IN ('user_id', 'product_id', 'order_item_id', 'rating', 'comment', 'user_height', 'user_weight', 'fit_rating', 'created_at', 'updated_at')) <> 10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: product_reviews'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='product_reviews' AND column_name NOT IN ('user_id', 'product_id', 'order_item_id', 'rating', 'comment', 'user_height', 'user_weight', 'fit_rating', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: product_reviews'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='product_review_images' AND engine='InnoDB') <> 1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing InnoDB Entity table: product_review_images'; END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='product_review_images' AND column_name IN ('product_review_id', 'image_url', 'media_type', 'display_order', 'created_at', 'updated_at')) <> 6 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Entity columns do not match: product_review_images'; END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='product_review_images' AND column_name NOT IN ('product_review_id', 'image_url', 'media_type', 'display_order', 'created_at', 'updated_at') AND is_nullable='NO' AND column_default IS NULL AND extra NOT LIKE '%auto_increment%' AND extra NOT LIKE '%GENERATED%') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unexpected required columns: product_review_images'; END IF;
  IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='orders' AND column_name='delivered_at') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chay Spring Boot ban moi de tao cot orders.delivered_at truoc'; END IF;
  START TRANSACTION;
  SET v_tx_started=TRUE;
  SET v_coolmate_exists=(EXISTS(SELECT 1 FROM `categories` WHERE LEFT(slug, 11) = 'fw-demo-v1-') OR EXISTS(SELECT 1 FROM `products` WHERE LEFT(slug, 11) = 'fw-demo-v1-') OR EXISTS(SELECT 1 FROM `product_variants` WHERE LEFT(sku, 8) = 'FWDEMO1-') OR EXISTS(SELECT 1 FROM `product_images` WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug, 11) = 'fw-demo-v1-')) OR EXISTS(SELECT 1 FROM `payment_methods` WHERE code IN ('FWDEMO1_COD', 'FWDEMO1_BANK')) OR EXISTS(SELECT 1 FROM `special_offers` WHERE LEFT(title, 13) = 'FW-DEMO-V1 | ') OR EXISTS(SELECT 1 FROM `special_offer_products` WHERE special_offer_id IN (SELECT id FROM special_offers WHERE LEFT(title, 13) = 'FW-DEMO-V1 | ')) OR EXISTS(SELECT 1 FROM `orders` WHERE LEFT(order_code, 5) = 'FWD1-') OR EXISTS(SELECT 1 FROM `order_items` WHERE order_id IN (SELECT id FROM orders WHERE LEFT(order_code, 5) = 'FWD1-')) OR EXISTS(SELECT 1 FROM `payment_transactions` WHERE order_id IN (SELECT id FROM orders WHERE LEFT(order_code, 5) = 'FWD1-')) OR EXISTS(SELECT 1 FROM `return_requests` WHERE LEFT(return_code, 5) = 'FWR1-') OR EXISTS(SELECT 1 FROM `return_request_items` WHERE return_request_id IN (SELECT id FROM return_requests WHERE LEFT(return_code, 5) = 'FWR1-')) OR EXISTS(SELECT 1 FROM `return_request_images` WHERE return_request_id IN (SELECT id FROM return_requests WHERE LEFT(return_code, 5) = 'FWR1-')) OR EXISTS(SELECT 1 FROM `product_reviews` WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug,11)='fw-demo-v1-')) OR EXISTS(SELECT 1 FROM `product_review_images` WHERE product_review_id IN (SELECT id FROM product_reviews WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug,11)='fw-demo-v1-'))));
  IF v_coolmate_exists THEN
    IF (SELECT COUNT(*) FROM `categories` WHERE LEFT(slug, 11) = 'fw-demo-v1-') <>11 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: categories'; END IF;
    IF (SELECT COUNT(*) FROM `products` WHERE LEFT(slug, 11) = 'fw-demo-v1-') <>50 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: products'; END IF;
    IF (SELECT COUNT(*) FROM `product_variants` WHERE LEFT(sku, 8) = 'FWDEMO1-') <>701 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: product_variants'; END IF;
    IF (SELECT COUNT(*) FROM `product_images` WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug, 11) = 'fw-demo-v1-')) <>148 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: product_images'; END IF;
    IF (SELECT COUNT(*) FROM `payment_methods` WHERE code IN ('FWDEMO1_COD', 'FWDEMO1_BANK')) <>2 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: payment_methods'; END IF;
    IF (SELECT COUNT(*) FROM `special_offers` WHERE LEFT(title, 13) = 'FW-DEMO-V1 | ') <>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: special_offers'; END IF;
    IF (SELECT COUNT(*) FROM `special_offer_products` WHERE special_offer_id IN (SELECT id FROM special_offers WHERE LEFT(title, 13) = 'FW-DEMO-V1 | ')) <>40 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: special_offer_products'; END IF;
    IF (SELECT COUNT(*) FROM `orders` WHERE LEFT(order_code, 5) = 'FWD1-') <>300 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: orders'; END IF;
    IF (SELECT COUNT(*) FROM `order_items` WHERE order_id IN (SELECT id FROM orders WHERE LEFT(order_code, 5) = 'FWD1-')) <>723 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: order_items'; END IF;
    IF (SELECT COUNT(*) FROM `payment_transactions` WHERE order_id IN (SELECT id FROM orders WHERE LEFT(order_code, 5) = 'FWD1-')) NOT IN (307,309) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: payment_transactions'; END IF;
    IF (SELECT COUNT(*) FROM `return_requests` WHERE LEFT(return_code, 5) = 'FWR1-') <>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: return_requests'; END IF;
    IF (SELECT COUNT(*) FROM `return_request_items` WHERE return_request_id IN (SELECT id FROM return_requests WHERE LEFT(return_code, 5) = 'FWR1-')) <>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: return_request_items'; END IF;
    IF (SELECT COUNT(*) FROM `return_request_images` WHERE return_request_id IN (SELECT id FROM return_requests WHERE LEFT(return_code, 5) = 'FWR1-')) <>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: return_request_images'; END IF;
    IF (SELECT COUNT(*) FROM `product_reviews` WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug,11)='fw-demo-v1-')) <>100 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: product_reviews'; END IF;
    IF (SELECT COUNT(*) FROM `product_review_images` WHERE product_review_id IN (SELECT id FROM product_reviews WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug,11)='fw-demo-v1-'))) <>30 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Batch coolmate thieu/xung dot: product_review_images'; END IF;
  END IF;
  SET v_owen_exists=(EXISTS(SELECT 1 FROM `categories` WHERE LEFT(slug,11)='fw-owen-v1-') OR EXISTS(SELECT 1 FROM `products` WHERE LEFT(slug,11)='fw-owen-v1-') OR EXISTS(SELECT 1 FROM `product_variants` WHERE LEFT(sku,8)='FWOWEN1-') OR EXISTS(SELECT 1 FROM `product_images` WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug,11)='fw-owen-v1-')));
  IF v_owen_exists THEN
