  -- Chi bo sung moc lich su da biet cho don demo; khong suy dien tu updated_at.
  UPDATE orders SET delivered_at=CAST(JSON_UNQUOTE(JSON_EXTRACT(notes,'$.delivery_at')) AS DATETIME)
  WHERE LEFT(order_code,5)='FWD1-' AND order_status='DELIVERED' AND delivered_at IS NULL
    AND CASE WHEN JSON_VALID(notes) THEN JSON_UNQUOTE(JSON_EXTRACT(notes,'$.batch'))='FW-DEMO-V2' ELSE FALSE END;
  IF EXISTS(SELECT 1 FROM orders WHERE LEFT(order_code,5)='FWD1-' AND
    ((order_status='DELIVERED' AND (delivered_at IS NULL OR NOT(delivered_at <=> CAST(JSON_UNQUOTE(JSON_EXTRACT(notes,'$.delivery_at')) AS DATETIME))))
      OR (order_status<>'DELIVERED' AND delivered_at IS NOT NULL)))
  THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai moc giao thanh cong cua don demo'; END IF;
  IF (SELECT COUNT(*) FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE LEFT(o.order_code,5)='FWD1-' AND (u.id IS NULL OR u.role<>'CUSTOMER' OR o.shipping_recipient_name<>COALESCE(NULLIF(u.fullname,''),u.username) OR o.shipping_phone<>COALESCE(NULLIF(u.phone,''),'0000000000')))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: order_customer'; END IF;
  IF (SELECT COUNT(*) FROM orders o JOIN users u ON u.id=o.user_id WHERE LEFT(o.order_code,5)='FWD1-' AND o.shipping_address<>COALESCE((SELECT full_address FROM user_addresses WHERE user_id=u.id ORDER BY is_default DESC,id LIMIT 1),CONCAT('Địa chỉ giao hàng mô phỏng của ',u.username,', Việt Nam (không giao hàng thật)')))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: order_address'; END IF;
  IF (SELECT COUNT(*) FROM order_items i JOIN orders o ON o.id=i.order_id LEFT JOIN product_variants v ON v.id=i.variant_id LEFT JOIN products p ON p.id=v.product_id WHERE LEFT(o.order_code,5)='FWD1-' AND (v.id IS NULL OR p.id IS NULL OR i.product_name<>p.name OR i.variant_info<>CONCAT(v.color,' / ',v.size) OR i.quantity<=0 OR i.unit_price<=0 OR i.original_price<i.unit_price OR i.total_price<>i.unit_price*i.quantity OR i.created_at<>o.created_at))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: line_product_snapshot'; END IF;
  IF (SELECT COUNT(*) FROM orders o WHERE LEFT(o.order_code,5)='FWD1-' AND (o.subtotal<>(SELECT SUM(i.total_price) FROM order_items i WHERE i.order_id=o.id) OR o.total_amount<>o.subtotal-o.discount_amount+o.shipping_fee OR o.discount_amount<>0 OR o.shipping_fee<>30000))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: order_total'; END IF;
  IF (SELECT COUNT(*) FROM order_items i JOIN orders o ON o.id=i.order_id JOIN product_variants v ON v.id=i.variant_id WHERE LEFT(o.order_code,5)='FWD1-' AND (i.original_price<>v.price OR i.unit_price<>COALESCE((SELECT FLOOR(i.original_price*(100-s.discount_percent)/100) FROM special_offers s JOIN special_offer_products sp ON sp.special_offer_id=s.id WHERE sp.product_id=v.product_id AND LEFT(s.title,13)='FW-DEMO-V1 | ' AND o.created_at>=s.start_date AND o.created_at<s.end_date),i.original_price)))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: line_discount'; END IF;
  IF (SELECT COUNT(*) FROM orders o WHERE LEFT(o.order_code,5)='FWD1-' AND ((o.payment_status IN ('PAID','REFUNDED') AND (SELECT COUNT(*) FROM payment_transactions t WHERE t.order_id=o.id AND t.status='SUCCESS' AND t.amount=o.total_amount AND t.paid_at IS NOT NULL)<>1) OR (o.payment_status IN ('PENDING','FAILED') AND EXISTS(SELECT 1 FROM payment_transactions t WHERE t.order_id=o.id AND t.status IN ('SUCCESS','REFUNDED'))) OR (o.order_status='CANCELLED' AND o.payment_status<>'FAILED') OR (o.order_status='DELIVERED' AND o.payment_status NOT IN ('PAID','REFUNDED'))))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: collection'; END IF;
  IF (SELECT COUNT(*) FROM payment_transactions t JOIN orders o ON o.id=t.order_id WHERE LEFT(o.order_code,5)='FWD1-' AND (t.amount<=0 OR t.created_at<o.created_at OR t.updated_at<t.created_at OR (t.status IN ('SUCCESS','REFUNDED') AND (t.paid_at IS NULL OR t.paid_at<t.created_at OR t.paid_at>t.updated_at)) OR (t.status IN ('PENDING','FAILED') AND t.paid_at IS NOT NULL)))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: payment_time'; END IF;
  IF (SELECT COUNT(*) FROM return_requests r JOIN orders o ON o.id=r.order_id JOIN return_request_items ri ON ri.return_request_id=r.id JOIN order_items i ON i.id=ri.order_item_id WHERE LEFT(r.return_code,5)='FWR1-' AND (r.request_type<>'RETURN' OR r.user_id<>o.user_id OR i.order_id<>o.id OR ri.old_variant_id<>i.variant_id OR ri.new_variant_id IS NOT NULL OR ri.quantity<=0 OR ri.quantity>i.quantity OR o.order_status<>'DELIVERED' OR r.created_at<o.delivered_at OR r.created_at>DATE_ADD(o.delivered_at,INTERVAL 7 DAY)))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: return_ownership'; END IF;
  IF (SELECT COUNT(*) FROM order_items i JOIN orders o ON o.id=i.order_id WHERE LEFT(o.order_code,5)='FWD1-' AND (SELECT COALESCE(SUM(ri.quantity),0) FROM return_request_items ri JOIN return_requests r ON r.id=ri.return_request_id WHERE ri.order_item_id=i.id AND r.status<>'REJECTED')>i.quantity)<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: return_quantity'; END IF;
  IF (SELECT COUNT(*) FROM return_requests r JOIN orders o ON o.id=r.order_id WHERE LEFT(r.return_code,5)='FWR1-' AND ((r.status='COMPLETED' AND (o.payment_status<>'REFUNDED' OR (SELECT COUNT(*) FROM payment_transactions t JOIN payment_methods pm ON pm.id=t.payment_method_id WHERE t.order_id=o.id AND t.status='REFUNDED' AND JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.return_code'))=r.return_code AND pm.code='FWDEMO1_BANK' AND t.amount=CAST(JSON_UNQUOTE(JSON_EXTRACT(r.reason_detail,'$.net_refund')) AS DECIMAL(18,2)) AND t.paid_at=r.updated_at)<>1)) OR (r.status<>'COMPLETED' AND (o.payment_status<>'PAID' OR EXISTS(SELECT 1 FROM payment_transactions t WHERE t.order_id=o.id AND t.status='REFUNDED')))))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: completed_refund'; END IF;
  IF (SELECT COUNT(*) FROM payment_transactions t JOIN orders o ON o.id=t.order_id WHERE LEFT(o.order_code,5)='FWD1-' AND t.status='REFUNDED' AND (t.amount<>o.subtotal-25000 OR t.amount>=o.total_amount OR JSON_EXTRACT(t.gateway_response,'$.original_shipping_refund')<>0 OR JSON_EXTRACT(t.gateway_response,'$.return_shipping_fee')<>25000 OR JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.inspection_accepted_at'))>DATE_FORMAT(t.paid_at,'%Y-%m-%d %H:%i:%s') OR JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.warehouse_received_at'))>JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.inspection_accepted_at')) OR JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.fee_consent_at'))>JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.warehouse_received_at')) OR JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.proof_is_simulated'))<>'true'))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: refund_policy'; END IF;
  IF (SELECT COUNT(*) FROM payment_transactions t JOIN orders o ON o.id=t.order_id WHERE LEFT(o.order_code,5)='FWD1-' AND t.status='REFUNDED' AND (JSON_CONTAINS_PATH(t.gateway_response,'all','$.warehouse_received_at','$.inspection_accepted_at','$.fee_consent_at','$.bank_details_confirmed_at','$.proof_reference')=0 OR COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.warehouse_received_at')),'null'),'')='' OR COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.inspection_accepted_at')),'null'),'')='' OR COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.fee_consent_at')),'null'),'')='' OR COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.bank_details_confirmed_at')),'null'),'')='' OR COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.proof_reference')),'null'),'')='' OR JSON_UNQUOTE(JSON_EXTRACT(t.gateway_response,'$.bank_details_confirmed_at'))>DATE_FORMAT(t.paid_at,'%Y-%m-%d %H:%i:%s')))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: refund_required_evidence'; END IF;
  IF (SELECT COUNT(*) FROM product_reviews r JOIN order_items i ON i.id=r.order_item_id JOIN orders o ON o.id=i.order_id JOIN product_variants v ON v.id=i.variant_id JOIN products p ON p.id=r.product_id WHERE LEFT(p.slug,11)='fw-demo-v1-' AND (r.user_id<>o.user_id OR r.product_id<>v.product_id OR o.order_status<>'DELIVERED' OR r.created_at<o.delivered_at OR r.rating NOT BETWEEN 1 AND 5))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: review_purchase'; END IF;
  IF (SELECT COUNT(*) FROM products p WHERE LEFT(p.slug,11)='fw-demo-v1-' AND (p.review_count<>(SELECT COUNT(*) FROM product_reviews r WHERE r.product_id=p.id) OR NOT(p.average_rating<=>(SELECT ROUND(AVG(r.rating),1) FROM product_reviews r WHERE r.product_id=p.id))))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: product_rating'; END IF;
  IF (SELECT COUNT(*) FROM product_review_images im JOIN product_reviews r ON r.id=im.product_review_id JOIN products p ON p.id=r.product_id WHERE LEFT(p.slug,11)='fw-demo-v1-' AND NOT EXISTS(SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.image_url=im.image_url))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: image_product'; END IF;
  IF (SELECT COUNT(*) FROM return_request_images im JOIN return_requests r ON r.id=im.return_request_id JOIN return_request_items ri ON ri.return_request_id=r.id JOIN order_items i ON i.id=ri.order_item_id JOIN product_variants v ON v.id=i.variant_id WHERE LEFT(r.return_code,5)='FWR1-' AND NOT EXISTS(SELECT 1 FROM product_images pi WHERE pi.product_id=v.product_id AND pi.image_url=im.image_url))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: return_image'; END IF;
  IF (SELECT COUNT(*) FROM product_variants v JOIN products p ON p.id=v.product_id WHERE LEFT(p.slug,11) IN ('fw-demo-v1-','fw-owen-v1-') AND (v.stock_quantity<0 OR v.price<=0 OR v.color IS NULL OR v.size IS NULL))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: stock'; END IF;
  IF (SELECT COUNT(*) FROM orders o WHERE LEFT(o.order_code,5)='FWD1-' AND (o.created_at<'2026-01-01' OR o.created_at>'2026-10-22 12:00:00' OR o.updated_at<o.created_at OR o.updated_at>'2026-10-22 12:00:00' OR JSON_UNQUOTE(JSON_EXTRACT(o.notes,'$.historical_import'))<>'true'))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong hop le: order_history'; END IF;
  IF (SELECT COUNT(*) FROM `categories` WHERE LEFT(slug, 11) = 'fw-demo-v1-')<>11 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/categories'; END IF;
  IF (SELECT COUNT(*) FROM `products` WHERE LEFT(slug, 11) = 'fw-demo-v1-')<>50 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/products'; END IF;
  IF (SELECT COUNT(*) FROM `product_variants` WHERE LEFT(sku, 8) = 'FWDEMO1-')<>701 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/product_variants'; END IF;
  IF (SELECT COUNT(*) FROM `product_images` WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug, 11) = 'fw-demo-v1-'))<>148 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/product_images'; END IF;
  IF (SELECT COUNT(*) FROM `payment_methods` WHERE code IN ('FWDEMO1_COD', 'FWDEMO1_BANK'))<>2 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/payment_methods'; END IF;
  IF (SELECT COUNT(*) FROM `special_offers` WHERE LEFT(title, 13) = 'FW-DEMO-V1 | ')<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/special_offers'; END IF;
  IF (SELECT COUNT(*) FROM `special_offer_products` WHERE special_offer_id IN (SELECT id FROM special_offers WHERE LEFT(title, 13) = 'FW-DEMO-V1 | '))<>40 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/special_offer_products'; END IF;
  IF (SELECT COUNT(*) FROM `orders` WHERE LEFT(order_code, 5) = 'FWD1-')<>300 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/orders'; END IF;
  IF (SELECT COUNT(*) FROM `order_items` WHERE order_id IN (SELECT id FROM orders WHERE LEFT(order_code, 5) = 'FWD1-'))<>723 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/order_items'; END IF;
  IF (SELECT COUNT(*) FROM `payment_transactions` WHERE order_id IN (SELECT id FROM orders WHERE LEFT(order_code, 5) = 'FWD1-'))<>309 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/payment_transactions'; END IF;
  IF (SELECT COUNT(*) FROM `return_requests` WHERE LEFT(return_code, 5) = 'FWR1-')<>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/return_requests'; END IF;
  IF (SELECT COUNT(*) FROM `return_request_items` WHERE return_request_id IN (SELECT id FROM return_requests WHERE LEFT(return_code, 5) = 'FWR1-'))<>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/return_request_items'; END IF;
  IF (SELECT COUNT(*) FROM `return_request_images` WHERE return_request_id IN (SELECT id FROM return_requests WHERE LEFT(return_code, 5) = 'FWR1-'))<>10 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/return_request_images'; END IF;
  IF (SELECT COUNT(*) FROM `product_reviews` WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug,11)='fw-demo-v1-'))<>100 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/product_reviews'; END IF;
  IF (SELECT COUNT(*) FROM `product_review_images` WHERE product_review_id IN (SELECT id FROM product_reviews WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug,11)='fw-demo-v1-')))<>30 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong coolmate/product_review_images'; END IF;
  IF (SELECT COUNT(*) FROM `categories` WHERE LEFT(slug,11)='fw-owen-v1-')<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong owen/categories'; END IF;
  IF (SELECT COUNT(*) FROM `products` WHERE LEFT(slug,11)='fw-owen-v1-')<>20 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong owen/products'; END IF;
  IF (SELECT COUNT(*) FROM `product_variants` WHERE LEFT(sku,8)='FWOWEN1-')<>129 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong owen/product_variants'; END IF;
  IF (SELECT COUNT(*) FROM `product_images` WHERE product_id IN (SELECT id FROM products WHERE LEFT(slug,11)='fw-owen-v1-'))<>60 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai so luong owen/product_images'; END IF;
  COMMIT;
  SET v_tx_started=FALSE;
  DO RELEASE_LOCK(CONCAT('fashion-owen-v1:',MD5(DATABASE())));
  DO RELEASE_LOCK(CONCAT('fashion-demo-v1:',DATABASE()));
  SELECT IF(v_legacy,'MIGRATED_V1_TO_V2',IF(v_coolmate_exists AND v_owen_exists,'ALREADY_PRESENT','INSERTED')) AS ket_qua,70 AS san_pham,830 AS bien_the,300 AS don_hang,309 AS giao_dich,10 AS phieu_tra,4 AS giao_dich_hoan;
END^^
DELIMITER ;
